INSERT INTO categories (id, name, slug, description, image_url, sort_order) VALUES
('diwali-lights', 'Diwali Lights', 'diwali-lights', 'Luminous string lights, lanterns, and modern ambient festive lighting.', 'https://images.unsplash.com/photo-1514517521153-1be72277b32f?auto=format&fit=crop&w=800&q=80', 1),
('diyas-lamps', 'Diyas & Lamps', 'diyas-lamps', 'Handcrafted brass diyas, terracotta oil lamps, and smokeless LED diyas.', 'https://images.unsplash.com/photo-1605647540924-852290f6b0d5?auto=format&fit=crop&w=800&q=80', 2),
('rangoli-toran', 'Rangoli & Toran', 'rangoli-toran', 'Intricate brass and wooden rangoli stencils, organic colors, and auspicious door torans.', 'https://images.unsplash.com/photo-1576872381149-7847515ce5d8?auto=format&fit=crop&w=800&q=80', 3),
('gift-decoration', 'Gift & Decoration', 'gift-decoration', 'Artisanal puja thalis, marigold flower garlands, and luxury Diwali gift combos.', 'https://images.unsplash.com/photo-1513151233558-d860c5398176?auto=format&fit=crop&w=800&q=80', 4)
INSERT INTO products (id, name, slug, description, short_description, price, original_price, sku, stock, category_id, is_active, is_featured, image_url, additional_images, specifications) VALUES
('prod-001', 'Premium LED Fairy String Lights', 'premium-led-fairy-string-lights', 'Bring warm golden ambient enchantment to your home with our 20-meter heavy-duty copper wire LED fairy lights. Featuring 200 micro-LEDs that emit a soft golden glow, 8 dynamic lighting modes, and an energy-efficient waterproof adapter designed for Indian weather conditions.', '20-meter warm golden copper wire micro-LED string lights with 8 flashing modes.', 649, 999, 'DA-LIGHT-001', 45, 'diwali-lights', true, true, 'https://images.unsplash.com/photo-1514517521153-1be72277b32f?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1543258103-a62bdc069871?auto=format&fit=crop&w=800&q=80"]'::jsonb, '{"Length": "20 Meters", "LED Count": "200 LEDs"}'::jsonb),
('prod-002', 'Decorative Brass-Style Diya Set', 'decorative-brass-style-diya-set', 'An auspicious set of 6 antique gold finish brass-style metal diyas. Featuring ornate floral engravings and deep oil reservoirs that keep your sacred flame burning bright throughout the festive evening.', 'Pack of 6 royal antique brass-style oil diyas with ornate floral motifs.', 899, 1399, 'DA-DIYA-002', 30, 'diyas-lamps', true, true, 'https://images.unsplash.com/photo-1605647540924-852290f6b0d5?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1573055418049-c8e0b7e3403b?auto=format&fit=crop&w=800&q=80"]'::jsonb, '{"Set": "6 Pieces", "Material": "Brass-finish alloy"}'::jsonb),
('prod-003', 'Floral Door Toran', 'floral-door-toran', 'Welcome Goddess Lakshmi and esteemed guests with this handcrafted royal entrance bandhanwar toran. Crafted with vibrant saffron artificial marigolds, golden pearl beads, auspicious brass bells, and shimmering moti hangings.', 'Handcrafted 38-inch entrance door toran with golden pearls and marigolds.', 749, 1199, 'DA-TORAN-003', 25, 'rangoli-toran', true, true, 'https://images.unsplash.com/photo-1576872381149-7847515ce5d8?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Length": "38 Inches"}'::jsonb),
('prod-004', 'Decorative Rangoli Stencil Kit', 'decorative-rangoli-stencil-kit', 'Create flawless festive rangolis in seconds with our master 8-piece stencil kit. Contains laser-cut acrylic stencils featuring sacred Lakshmi steps, peacock plumes, lotus florets, and geometric mandalas, accompanied by 4 vibrant herbal non-toxic color dispensers.', '8-piece reusable acrylic stencil templates with 4 herbal color dispensers.', 499, 799, 'DA-RANG-004', 60, 'rangoli-toran', true, false, 'https://images.unsplash.com/photo-1574360773950-134376378ef8?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Contents": "8 Stencils + 4 Colors"}'::jsonb),
('prod-005', 'Flameless LED Candle Set', 'flameless-led-candle-set', 'Enjoy the mesmerizing beauty of traditional candle flames with complete safety for children and pets. This set of 12 ivory flameless LED tea-lights feature realistic 3D dancing wick flickers and come pre-fitted with long-lasting button batteries.', 'Box of 12 realistic dancing-wick battery LED tealight candles.', 549, 849, 'DA-CAND-005', 50, 'diyas-lamps', true, false, 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Quantity": "12 Tealights"}'::jsonb),
('prod-006', 'Lotus LED Decorative Lamp', 'lotus-led-decorative-lamp', 'Symbolizing divine purity and prosperity, this glowing lotus blossom lamp is crafted with multi-tiered crystal acrylic petals and a warm inner LED sphere. Emits a gentle sacred aura, making it an exquisite centerpiece.', 'Multilayer crystal petal lotus accent lamp with warm ambient glow.', 1199, 1799, 'DA-LOTUS-006', 20, 'diwali-lights', true, true, 'https://images.unsplash.com/photo-1519751138087-5bf79df62d5b?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Diameter": "22 cm"}'::jsonb),
('prod-007', 'Festive Paper Lantern Set', 'festive-paper-lantern-set', 'Celebrate the timeless tradition of the Akash Kandil with our set of 4 modern artisanal paper hanging lanterns. Features intricate lattice cut-outs that cast enchanting geometric shadows across your walls and balconies.', 'Pack of 4 traditional artisanal hanging kandeel paper lanterns.', 599, 899, 'DA-LANT-007', 35, 'diwali-lights', true, false, 'https://images.unsplash.com/photo-1508672019048-805c876b67e2?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Quantity": "4 Lanterns"}'::jsonb),
('prod-008', 'Premium Decorative Puja Thali', 'premium-decorative-puja-thali', 'An exquisitely designed 11-inch ceremonial puja plate cast in heavy brass with royal meenakari enamel work. Comes complete with a central Lakshmi-Ganesh engraving, attached diya stand, twin sindoor and roli bowls, and bell.', '11-inch handcrafted brass puja thali with intricate meenakari enamel work.', 1499, 2299, 'DA-THALI-008', 15, 'gift-decoration', true, true, 'https://images.unsplash.com/photo-1603555501671-8f96b3fce8b4?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Diameter": "11 Inches"}'::jsonb),
('prod-009', 'Artificial Marigold Flower Garland', 'artificial-marigold-flower-garland', 'Enjoy everlasting freshness without wilting. This pack of 5 vibrant 5-foot genda phool garlands is meticulously handcrafted with high-density fluffy fabric petals in auspicious saffron-orange and sunflower-yellow.', 'Pack of 5 lush 5-foot washable artificial yellow-orange marigold malas.', 499, 799, 'DA-GRLND-009', 70, 'gift-decoration', true, false, 'https://images.unsplash.com/photo-1576872381149-7847515ce5d8?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Length": "5 Feet x 5 pcs"}'::jsonb),
('prod-010', 'Luxury Diwali Home Decoration Combo', 'luxury-diwali-home-decoration-combo', 'The ultimate all-in-one celebration curation for the discerning home. This grand festive hamper includes: 2x 20m Copper String Lights, 1x Decorative Brass Diya Set (6pcs), 1x Handcrafted Entrance Toran, 2x Marigold Garlands, and 1x Lotus Accent Lamp.', 'The master festive hamper: lights, brass diyas, toran, marigolds & lotus lamp.', 3499, 5499, 'DA-COMBO-010', 12, 'gift-decoration', true, true, 'https://images.unsplash.com/photo-1513151233558-d860c5398176?auto=format&fit=crop&w=800&q=80', '[]'::jsonb, '{"Contents": "6 Luxury Items"}'::jsonb)
