INSERT INTO faqs (id, question, answer, category, sort_order, is_active) VALUES
('faq-001', 'How do I place an order on DeepAura?', 'Browse our festive collection, select your desired products and quantities, click "Add to Cart", and proceed to checkout.', 'Ordering', 1, true),
('faq-002', 'What are your delivery timelines for Diwali?', 'Orders are dispatched within 24 hours of placement. Standard delivery takes 3 to 5 business days across India.', 'Shipping', 2, true),
('faq-003', 'Is Cash on Delivery (COD) available?', 'Yes! We offer Cash on Delivery for all serviceable PIN codes across India on orders up to ₹5,000.', 'Payment', 3, true),
('faq-004', 'How do I apply a discount coupon?', 'In your Cart Drawer or at the Checkout page, enter your promotional coupon code (e.g. DIWALI15) in the "Discount Code" field and click Apply.', 'Discounts', 4, true),
('faq-005', 'What is your return and replacement policy?', 'If any festive decor item arrives broken or defective due to transit, simply notify our customer support team within 48 hours for a free replacement.', 'Returns', 5, true)
