-- DeepAura — Diwali Decor Starter Seed SQL
-- Inserts categories, starter products, discounts, FAQs, and settings

-- 1. Insert Categories
ON CONFLICT (id) DO NOTHING;

-- 2. Insert Exactly 10 Products
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  price = EXCLUDED.price,
  original_price = EXCLUDED.original_price,
  stock = EXCLUDED.stock;

-- 3. Insert Starter Discounts
ON CONFLICT (id) DO NOTHING;

-- 4. Insert Initial FAQs
ON CONFLICT (id) DO NOTHING;
